        ('BROWARY', 'P001,P002,P003,P004,P005,P006,P007,P008,P009,P010,P011,P012,P013,P014,P015,P016,P017,P018,P019,P020,P021,P022,P023,P024,P145,P026,P027,P028,P029,P030,P031,P032,P033,P034,P035,P036,P176,P177,P038,P039,P040,P041,P042,P043,P044,P045,P046,P047,P048,P049,P050,P051,P052,P053,P054,P055,P056,P057,P058,P064,P190,P065,P191,P066,P067,P068,P186,P069,P187,P070,P071,P075,P076,P077,P135,P082,P083,P084,P085,P086,P087,P088,P089,P090,P091,P092,P143,P144,P093,P094,P095,P096,P097,P098,P099,P100,P101,P102,P103,P104,P106,P107,P109,P111,P112,P113,P114,P116,P117,P118,P119,P121,P122,P123,P125,P127,P128,P184,P129,P131,P132,P133'),
        ('ELEKTROWNIA', 'P001,P002,P003,P004,P005,P006,P007,P008,P009,P010,P011,P012,P013,P014,P015,P016,P017,P018,P019,P020,P021,P022,P023,P024,P025,P026,P027,P028,P029,P030,P031,P032,P033,P034,P035,P036,P176,P177,P038,P039,P040,P042,P043,P044,P045,P046,P047,P048,P049,P050,P051,P052,P158,P054,P055,P064,P190,P065,P191,P066,P067,P068,P186,P069,P187,P070,P071,P156,P075,P076,P077,P082,P083,P084,P085,P086,P087,P088,P091,P092,P143,P144,P093,P094,P095,P096,P097,P098,P099,P100,P101,P102,P103,P104,P106,P107,P169,P111,P112,P113,P114,P116,P117,P118,P119,P121,P122,P123,P125,P127,P128,P129,P131,P132,P133'),
        ('FORUM', 'P001,P002,P003,P004,P005,P006,P007,P170,P008,P009,P010,P011,P012,P013,P014,P015,P016,P017,P018,P019,P020,P021,P022,P023,P024,P026,P027,P028,P029,P030,P031,P032,P033,P034,P035,P036,P176,P177,P038,P039,P040,P041,P042,P043,P044,P045,P046,P047,P048,P049,P050,P051,P052,P053,P054,P055,P056,P057,P058,P165,P155,P166,P167,P164,P163,P075,P076,P077,P082,P083,P084,P085,P086,P087,P088,P089,P090,P091,P092,P143,P144,P093,P094,P095,P096,P097,P098,P099,P100,P101,P102,P103,P104,P106,P107,P109,P111,P112,P113,P114,P116,P117,P118,P119,P121,P122,P123,P125,P127,P130,P129,P131,P132,P133'),
