        ('NORBLIN', 'P001,P002,P003,P004,P005,P006,P007,P008,P009,P010,P011,P012,P013,P014,P015,P016,P017,P018,P019,P020,P021,P022,P023,P024,P025,P145,P026,P027,P028,P029,P030,P031,P032,P033,P034,P035,P036,P176,P177,P038,P039,P040,P041,P042,P043,P044,P045,P046,P047,P048,P049,P050,P051,P052,P053,P054,P055,P056,P057,P058,P064,P190,P065,P191,P066,P067,P068,P186,P069,P187,P070,P071,P075,P076,P077,P082,P083,P084,P085,P086,P087,P088,P089,P090,P091,P092,P143,P144,P093,P094,P095,P096,P097,P098,P099,P100,P101,P102,P103,P104,P106,P107,P109,P111,P112,P113,P114,P116,P117,P118,P119,P121,P122,P123,P125,P127,P142,P129,P131,P132,P133'),
        ('SLONY', 'P001,P002,P003,P004,P005,P006,P007,P170,P008,P009,P010,P011,P012,P013,P014,P015,P016,P017,P018,P019,P020,P021,P022,P023,P024,P026,P027,P028,P029,P030,P031,P032,P033,P034,P035,P036,P176,P177,P038,P039,P040,P041,P042,P043,P044,P045,P046,P047,P048,P049,P050,P051,P052,P053,P054,P055,P056,P057,P058,P064,P190,P065,P191,P066,P067,P068,P186,P069,P187,P070,P071,P075,P076,P077,P082,P083,P084,P085,P086,P087,P088,P089,P090,P091,P092,P143,P144,P093,P094,P095,P096,P097,P098,P099,P100,P101,P102,P103,P104,P106,P107,P109,P111,P112,P113,P114,P116,P117,P118,P119,P121,P122,P123,P125,P127,P130,P129,P131,P132,P133'),
        ('STARY_BROWAR', 'P001,P002,P003,P004,P005,P006,P007,P170,P008,P009,P010,P011,P012,P013,P014,P015,P016,P017,P018,P019,P020,P021,P022,P023,P024,P025,P026,P027,P028,P029,P030,P031,P032,P033,P034,P035,P036,P176,P177,P038,P039,P040,P041,P042,P043,P044,P045,P046,P047,P048,P049,P050,P051,P052,P054,P055,P053,P056,P057,P058,P059,P060,P061,P062,P064,P190,P065,P191,P066,P067,P068,P186,P069,P187,P070,P071,P072,P073,P075,P076,P077,P138,P137,P157,P136,P156,P082,P083,P084,P085,P086,P087,P088,P089,P090,P091,P092,P093,P094,P095,P096,P097,P098,P099,P100,P101,P102,P175,P103,P104,P106,P107,P109,P110,P111,P112,P113,P114,P115,P116,P117,P118,P119,P120,P121,P122,P123,P124,P125,P126,P127,P130,P129,P183,P131,P132,P133'),
        ('SUPERSAM', 'P001,P002,P003,P004,P005,P006,P007,P170,P008,P009,P010,P011,P012,P013,P014,P015,P016,P017,P018,P019,P020,P021,P022,P023,P024,P026,P027,P028,P029,P030,P031,P032,P033,P034,P035,P036,P176,P177,P038,P039,P040,P041,P042,P043,P044,P045,P046,P047,P048,P049,P050,P051,P052,P053,P054,P055,P056,P057,P058,P064,P190,P065,P191,P066,P067,P068,P186,P069,P187,P070,P071,P075,P076,P077,P082,P083,P084,P085,P086,P087,P088,P089,P090,P091,P092,P143,P144,P093,P094,P095,P096,P097,P098,P099,P100,P101,P102,P103,P104,P106,P107,P109,P111,P112,P113,P114,P116,P117,P118,P119,P121,P122,P123,P125,P127,P183,P129,P131,P132,P133'),
        ('WESTFIELD', 'P001,P002,P003,P004,P005,P006,P007,P170,P008,P009,P010,P011,P012,P013,P014,P015,P016,P017,P018,P019,P020,P021,P022,P023,P024,P026,P027,P028,P029,P030,P031,P032,P033,P034,P035,P036,P176,P177,P038,P039,P040,P041,P042,P043,P044,P045,P046,P047,P048,P049,P050,P051,P052,P053,P054,P055,P056,P057,P058,P064,P190,P065,P191,P066,P067,P068,P186,P069,P187,P070,P071,P075,P076,P077,P082,P083,P084,P085,P086,P087,P088,P089,P090,P091,P092,P143,P144,P093,P094,P095,P096,P097,P098,P099,P100,P101,P102,P103,P104,P106,P107,P109,P111,P112,P113,P114,P116,P117,P118,P119,P121,P122,P123,P125,P127,P183,P129,P131,P132,P133'),
        ('WOLA', 'P001,P002,P003,P004,P005,P006,P007,P008,P009,P010,P011,P012,P013,P014,P015,P016,P017,P018,P019,P020,P021,P022,P023,P024,P025,P026,P027,P028,P029,P030,P031,P032,P033,P034,P035,P036,P176,P177,P038,P039,P040,P041,P042,P043,P044,P045,P046,P047,P048,P049,P050,P051,P052,P053,P054,P055,P056,P057,P058,P059,P061,P063,P064,P190,P065,P191,P066,P067,P068,P186,P069,P187,P079,P070,P071,P072,P073,P074,P136,P157,P137,P138,P075,P076,P077,P080,P081,P082,P083,P084,P085,P086,P087,P088,P089,P090,P091,P092,P093,P094,P095,P096,P097,P098,P099,P100,P101,P102,P103,P104,P105,P106,P107,P108,P109,P110,P111,P112,P113,P114,P115,P116,P117,P118,P119,P120,P121,P122,P123,P124,P125,P126,P127,P128,P129,P130,P131,P132,P133,P181,P182')
    ) AS l(loc, ids)
    CROSS JOIN LATERAL unnest(string_to_array(l.ids, ',')) WITH ORDINALITY AS u(pid, ord);
    GET DIAGNOSTICS v_n = ROW_COUNT;
    IF v_n <> 1514 THEN RAISE EXCEPTION 'card rows: expected 1514, got %', v_n; END IF;

    -- 2a. Clear everything first so a re-run is exact.
    UPDATE products SET inventory_order = NULL WHERE inventory_order IS NOT NULL;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    IF v_n <> 0 THEN RAISE EXCEPTION '2a products clear: expected 0, got %', v_n; END IF;
    UPDATE location_product_settings SET inventory_order = NULL WHERE inventory_order IS NOT NULL;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    IF v_n <> 0 THEN RAISE EXCEPTION '2a settings clear: expected 0, got %', v_n; END IF;

    -- 2b. Template.
    UPDATE products AS p
    SET inventory_order = t.pos
    FROM (SELECT split_part(x, ':', 1) AS product_id, split_part(x, ':', 2)::integer AS pos
          FROM unnest(string_to_array('P001:10,P162:20,P172:30,P002:40,P003:50,P004:60,P005:70,P006:80,P007:90,P170:100,P008:110,P009:120,P010:130,P011:140,P012:150,P013:160,P014:170,P015:180,P016:190,P017:200,P018:210,P019:220,P020:230,P021:240,P022:250,P023:260,P024:270,P145:280,P179:290,P025:300,P026:310,P027:320,P028:330,P029:340,P030:350,P031:360,P032:370,P033:380,P034:390,P035:400,P036:410,P176:420,P177:430,P178:440,P185:450,P038:460,P039:470,P040:480,P041:490,P042:500,P043:510,P044:520,P045:530,P046:540,P047:550,P048:560,P049:570,P050:580,P051:590,P052:600,P158:610,P053:620,P054:630,P055:640,P056:650,P057:660,P058:670,P165:680,P155:690,P166:700,P167:710,P164:720,P163:730,P059:740,P060:750,P061:760,P062:770,P063:780,P064:790,P190:800,P065:810,P191:820,P066:830,P067:840,P068:850,P186:860,P069:870,P187:880,P156:890,P079:900,P070:910,P071:920,P072:930,P073:940,P074:950,P136:960,P157:970,P137:980,P138:990,P075:1000,P076:1010,P077:1020,P135:1030,P080:1040,P081:1050,P082:1060,P083:1070,P084:1080,P085:1090,P086:1100,P087:1110,P088:1120,P089:1130,P173:1140,P090:1150,P091:1160,P092:1170,P143:1180,P144:1190,P093:1200,P094:1210,P095:1220,P096:1230,P097:1240,P098:1250,P099:1260,P100:1270,P101:1280,P102:1290,P175:1300,P103:1310,P104:1320,P105:1330,P106:1340,P107:1350,P169:1360,P108:1370,P109:1380,P110:1390,P111:1400,P112:1410,P113:1420,P114:1430,P115:1440,P116:1450,P117:1460,P118:1470,P119:1480,P120:1490,P121:1500,P122:1510,P123:1520,P124:1530,P125:1540,P126:1550,P127:1560,P142:1570,P184:1580,P128:1590,P129:1600,P130:1610,P183:1620,P131:1630,P132:1640,P133:1650,P181:1660,P182:1670', ',')) AS x) AS t(product_id, pos)
    WHERE p.product_id = t.product_id;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    IF v_n <> 167 THEN RAISE EXCEPTION '2b template: expected 167, got %', v_n; END IF;

    -- 2c. Card overrides.
    UPDATE location_product_settings AS s
    SET inventory_order = o.pos
    FROM (VALUES
    ('BRACKA', 'P053', 645),
    ('BRACKA', 'P081', 923),
    ('BRACKA', 'P079', 926),
    ('BRACKA', 'P080', 975),
    ('BRACKA', 'P138', 1028),
    ('BRACKA', 'P137', 1036),
    ('BRACKA', 'P157', 1044),
    ('BRACKA', 'P136', 1052),
    ('BROWARY', 'P184', 1595),
    ('ELEKTROWNIA', 'P156', 960),
    ('FORUM', 'P129', 1620),
    ('KAMIENICA', 'P129', 1620),
    ('KEN', 'P081', 900),
    ('KEN', 'P138', 950),
    ('KEN', 'P074', 990),
    ('NORBLIN', 'P145', 305),
    ('SLONY', 'P129', 1620),
    ('STARY_BROWAR', 'P053', 645),
    ('STARY_BROWAR', 'P138', 1026),
    ('STARY_BROWAR', 'P137', 1033),
    ('STARY_BROWAR', 'P157', 1040),
    ('STARY_BROWAR', 'P136', 1046),
    ('STARY_BROWAR', 'P156', 1053),
    ('STARY_BROWAR', 'P129', 1615),
    ('SUPERSAM', 'P129', 1625),
    ('WESTFIELD', 'P129', 1625)
    ) AS o(location_id, product_id, pos)
    WHERE s.location_id = o.location_id AND s.product_id = o.product_id;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    IF v_n <> 26 THEN RAISE EXCEPTION '2c overrides: expected 26, got %', v_n; END IF;

    -- 2d. Extras: section end + 1, computed from the card's effective positions and
    --     prod's product_category (ties among extras break by product_id).
    --     "+ 1" relies on a gap of at least 2 before the next section's first
    --     position (template and overrides step by 10); the 3d check below is the
    --     tripwire. Settings of inactive products are positioned too, on purpose:
    --     they never render, and a re-activated product already sits at its
    --     section end.
    WITH card_eff AS (
        SELECT c.location_id, p.product_category,
               COALESCE(s.inventory_order, p.inventory_order) AS e
        FROM inv_card c
        JOIN products p ON p.product_id = c.product_id
        LEFT JOIN location_product_settings s
               ON s.location_id = c.location_id AND s.product_id = c.product_id
    ),
    section_end AS (
        SELECT location_id, product_category, max(e) AS se
        FROM card_eff GROUP BY 1, 2
    )
    UPDATE location_product_settings AS s
    SET inventory_order = se.se + 1
    FROM products p, section_end se
    WHERE p.product_id = s.product_id
      AND se.location_id = s.location_id
      AND se.product_category = p.product_category
      AND NOT EXISTS (SELECT 1 FROM inv_card c
                      WHERE c.location_id = s.location_id AND c.product_id = s.product_id);
    GET DIAGNOSTICS v_n = ROW_COUNT;
    IF v_n <> 112 THEN RAISE EXCEPTION '2d extras: expected 112, got %', v_n; END IF;

    -- A1. Card order holds everywhere (audit 3c).
    SELECT count(*) INTO v_n FROM (
        SELECT c.seq,
               lag(c.seq) OVER (PARTITION BY c.location_id
                                ORDER BY COALESCE(s.inventory_order, p.inventory_order) NULLS LAST,
                                         c.product_id) AS prev_seq
        FROM inv_card c
        JOIN location_product_settings s
          ON s.location_id = c.location_id AND s.product_id = c.product_id
        JOIN products p ON p.product_id = c.product_id
    ) r WHERE r.prev_seq > r.seq;
    IF v_n <> 0 THEN RAISE EXCEPTION 'A1 card-order inversions: %', v_n; END IF;

    -- A2. Contiguity (audit 3d).
    WITH eff AS (
        SELECT s.location_id, s.product_id, p.product_category, p.active,
               COALESCE(s.inventory_order, p.inventory_order) AS e
        FROM location_product_settings s
        JOIN products p ON p.product_id = s.product_id
    ),
    listed AS (
        SELECT e.*, row_number() OVER (PARTITION BY e.location_id
                                       ORDER BY e.e NULLS LAST, e.product_id) AS rn,
               EXISTS (SELECT 1 FROM inv_card c
                       WHERE c.location_id = e.location_id AND c.product_id = e.product_id) AS on_card
        FROM eff e
        WHERE e.active AND e.location_id IN (SELECT DISTINCT location_id FROM inv_card)
    ),
    sections AS (
        SELECT location_id, product_category, min(rn) AS lo, max(rn) AS hi
        FROM listed WHERE on_card GROUP BY 1, 2
    )
    SELECT count(*) INTO v_n
    FROM listed l
    JOIN sections sec ON sec.location_id = l.location_id AND l.rn BETWEEN sec.lo AND sec.hi
    WHERE NOT l.on_card;
    IF v_n <> 0 THEN RAISE EXCEPTION 'A2 contiguity breaks: %', v_n; END IF;

    -- A3. Totals (audits 3a, 3e).
    SELECT count(*) INTO v_n FROM products WHERE inventory_order IS NOT NULL;
    IF v_n <> 167 THEN RAISE EXCEPTION 'A3 positioned products: expected 167, got %', v_n; END IF;
    SELECT count(*) INTO v_n FROM location_product_settings WHERE inventory_order IS NOT NULL;
    IF v_n <> 138 THEN
        RAISE EXCEPTION 'A3 positioned settings: expected 138, got %', v_n;
    END IF;
    SELECT count(*) INTO v_n
    FROM location_product_settings s JOIN products p ON p.product_id = s.product_id
    WHERE p.active AND COALESCE(s.inventory_order, p.inventory_order) IS NULL;
    IF v_n <> 0 THEN
        RAISE EXCEPTION 'A3 unpositioned active settings: expected 0, got %', v_n;
    END IF;
END $$;

-- Transcription check (main lane, 17.10): card and template data equal the reviewed file.
DO $$
BEGIN
    IF (SELECT md5(string_agg(location_id || ':' || seq || ':' || product_id, ',' ORDER BY location_id COLLATE "C", seq)) FROM inv_card)
       IS DISTINCT FROM '34685dd85a30056bd3587480733f55e4' THEN
        RAISE EXCEPTION 'X1 inv_card differs from the reviewed file';
    END IF;
    IF (SELECT md5(string_agg(product_id || ':' || inventory_order, ',' ORDER BY product_id COLLATE "C", inventory_order)) FROM products WHERE inventory_order IS NOT NULL)
       IS DISTINCT FROM 'f612c2b52ec55f203dc858f060566cea' THEN
        RAISE EXCEPTION 'X2 template positions differ from the reviewed file';
    END IF;
END $$;

COMMIT;
